    if (formData.guests < 1) newErrors.guests = 'Please enter a valid number of guests.';
    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validate();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSuccess(true);
      setTimeout(() => {
        setIsSuccess(false);
        setFormData(initialReservation);
      }, 2000);
    }, 1200);
  };

  return (
    <div className="w-full max-w-6xl mx-auto p-6 sm:p-8 bg-white shadow-2xl rounded-2xl border border-stone-200 transition-all duration-300 hover:-translate-y-1 hover:shadow-xl">
      {/* Header */}
