          </div>
        </div>
        <button
          onClick={() => setLocation(defaultLocation)}
          className="px-4 py-2 rounded-xl bg-white border border-stone-300 text-stone-600 hover:text-stone-800 hover:bg-stone-50 transition-colors"
        >
          Default Location
        </button>
      </div>

      {/* Location & Details */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-8">
        <div className="p-6 rounded-2xl bg-amber-900/5 border border-stone-900/10 shadow-inner flex flex-col justify-between h-full transition-all duration-300 hover:-translate-y-1 hover:shadow-xl">
          <div>
            <h3 className="font-display text-stone-600 text-sm uppercase tracking-wider mb-2">Restaurant Details</h3>
            <p className="text-stone-600 text-sm">{location.name}</p>
            <p className="text-stone-600 text-sm font-light mb-4">{location.address}</p>
            <div className="mt-4">
              <span className="inline-flex items-center gap-1 text-xs text-stone-500"><MapPin className="w-3 h-3" /> {location.phone}</span>
              <span className="inline-flex items-center gap-1 text-xs text-stone-500 mt-1"><Mail className="w-3 h-3" /> {location.email}</span>
            </div>
          </div>
          <div className="mt-6 sm:mt-0">
            <button
              onClick={() => setLocation({
                name: "Sushi Savor",
                address: "456 S Congress Ave, Austin, TX 78704",
                phone: "(512) 222-2222",
                email: "sushi@savoraustin.com",
              })}
              className="self-start px-4 py-2 rounded-xl bg-amber-500/10 text-amber-400 border border-amber-500/20 hover:text-amber-300 transition-colors"
            >
              Change Location
            </button>
          </div>
        </div>
        <div className="p-6 rounded-2xl bg-amber-900/5 border border-stone-900/10 shadow-inner flex flex-col justify-between h-full transition-all duration-300 hover:-translate-y-1 hover:shadow-xl">
          <div>
            <h3 className="font-display text-stone-600 text-sm uppercase tracking-wider mb-2">Open Hours</h3>
            <p className="text-stone-600 text-sm">Monday - Friday: 11:00 AM - 10:00 PM</p>
            <p className="text-stone-600 text-sm font-light mb-4">Saturday - Sunday: 11:00 AM - 11:00 PM</p>
            <p className="text-stone-600 text-xs mt-2 text-right">Closed on Major Holidays</p>
          </div>
          <div className="mt-6 sm:mt-0">
            <button
              onClick={() => setLocation({
                name: "Sushi Savor",
                address: "456 S Congress Ave, Austin, TX 78704",
                phone: "(512) 222-2222",
                email: "sushi@savoraustin.com",
              })}
              className="self-start px-4 py-2 rounded-xl bg-amber-500/10 text-amber-400 border border-amber-500/20 hover:text-amber-300 transition-colors"
            >
              Schedule Tour
            </button>
          </div>
        </div>
      </div>

      {/* Reservation Form */}
      <form onSubmit={handleSubmit} className="space-y-6">
        {isSuccess ? (
          <div className="py-12 flex flex-col items-center justify-center text-center">
            <div className="w-16 h-16 rounded-full bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 flex items-center justify-center animate-pulse mb-6">
              <CheckCircle2 className="w-8 h-8" />
            </div>
            <h3 className="font-display text-xl font-bold text-stone-900">Reservation Confirmed!</h3>
            <p className="text-sm text-stone-600">We've saved your table. Check your confirmation email.</p>
